test("title-becomes-url-slug: a title becomes a slug that can be put in a URL", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("lower-case: upper-case letters are turned into lower case", () => {
  assert.equal(slugify("Hello"), "hello");
});

test("space-becomes-dash: a space between words becomes a dash", () => {
  assert.equal(slugify("big world"), "big-world");
});

test("space-run-becomes-one-dash: a run of several spaces becomes one dash", () => {
  assert.equal(slugify("hello   big"), "hello-big");
});

test("punctuation-dropped: punctuation is dropped", () => {
  assert.equal(slugify("hello, world!"), "hello-world");
});

test("accented-letters-dropped: accented letters are dropped, not converted to a plain letter", () => {
  assert.equal(slugify("héllo"), "hllo");
});

test("digits-kept: digits are kept", () => {
  assert.equal(slugify("wrld 42"), "wrld-42");
});

test('title-becomes-url-slug: "Hello World" becomes "hello-world"', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('lower-case: "Hello" becomes "hello"', () => {
  assert.equal(slugify('Hello'), 'hello');
});

test('space-becomes-dash: "big world" becomes "big-world"', () => {
  assert.equal(slugify('big world'), 'big-world');
});

test('space-run-single-dash: "hello   big world" becomes "hello-big-world"', () => {
  assert.equal(slugify('hello   big world'), 'hello-big-world');
});

test('punctuation-dropped: "wow!" becomes "wow"', () => {
  assert.equal(slugify('wow!'), 'wow');
});

test('accented-letters-dropped: "héllo" becomes "hllo"', () => {
  assert.equal(slugify('héllo'), 'hllo');
});

test('digits-kept: "abc123" becomes "abc123"', () => {
  assert.equal(slugify('abc123'), 'abc123');
  // The example alone passes on code that returns the title unchanged,
  // so also check digits survive when the title really is transformed.
  assert.equal(slugify('ABC123'), 'abc123');
});

