test('combined-hours-minutes: "1h30m" returns 5400', () => {
  assert.equal(parseDuration('1h30m'), 5400);
});

test('seconds-unit: "45s" returns 45', () => {
  assert.equal(parseDuration('45s'), 45);
});

test('minutes-unit: "2m" returns 120', () => {
  assert.equal(parseDuration('2m'), 120);
});

test('hours-unit: "1h" returns 3600', () => {
  assert.equal(parseDuration('1h'), 3600);
});

test('three-units-combined: "1h30m15s" returns 5415', () => {
  assert.equal(parseDuration('1h30m15s'), 5415);
});

// The null criteria below already hold for the stub, which returns null for
// everything. Each one also asserts a closely related valid input so it only
// passes once parseDuration actually tells the two apart.

test('not-a-duration-null: "abc" returns null', () => {
  assert.equal(parseDuration('abc'), null);
  assert.equal(parseDuration('1s'), 1);
});

test('empty-string-null: "" returns null', () => {
  assert.equal(parseDuration(''), null);
  assert.equal(parseDuration('1s'), 1);
});

test('unknown-unit-null: "1x" returns null', () => {
  assert.equal(parseDuration('1x'), null);
  assert.equal(parseDuration('1s'), 1);
});

test('wrong-order-null: "30m1h" returns null', () => {
  assert.equal(parseDuration('30m1h'), null);
  assert.equal(parseDuration('1h30m'), 5400);
});

test('repeated-unit-null: "1h1h" returns null', () => {
  assert.equal(parseDuration('1h1h'), null);
  assert.equal(parseDuration('1h'), 3600);
});

test('bare-number-seconds: "90" returns 90', () => {
  assert.equal(parseDuration('90'), 90);
});

test('spaces-between-parts: "1h 30m" returns 5400', () => {
  assert.equal(parseDuration('1h 30m'), 5400);
});

test('upper-case-units: "1H30M" returns 5400', () => {
  assert.equal(parseDuration('1H30M'), 5400);
});

test('decimal-part: "1.5h" returns 5400', () => {
  assert.equal(parseDuration('1.5h'), 5400);
});

test("combined-hours-minutes: hours and minutes give the total seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("seconds-unit: a number followed by s counts as seconds", () => {
  assert.equal(parseDuration("45s"), 45);
});

test("minutes-unit: a number followed by m counts as minutes", () => {
  assert.equal(parseDuration("2m"), 120);
});

test("hours-unit: a number followed by h counts as hours", () => {
  assert.equal(parseDuration("1h"), 3600);
});

test("three-units-combined: hours, minutes and seconds are added up", () => {
  assert.equal(parseDuration("1h30m15s"), 5415);
});

test("not-a-duration-is-null: text with no number gives null", () => {
  assert.equal(parseDuration("abc"), null);
  // The stub returns null for everything, so check a real duration still parses.
  assert.equal(parseDuration("45s"), 45);
});

test("unknown-unit-is-null: a unit other than h, m or s gives null", () => {
  assert.equal(parseDuration("1x"), null);
  // The stub returns null for everything, so check a known unit still parses.
  assert.equal(parseDuration("1h"), 3600);
});

test("empty-is-null: empty text gives null", () => {
  assert.equal(parseDuration(""), null);
  // The stub returns null for everything, so check non-empty text still parses.
  assert.equal(parseDuration("45s"), 45);
});

test("wrong-order-is-null: units out of largest-to-smallest order give null", () => {
  assert.equal(parseDuration("30m1h"), null);
  // The stub returns null for everything, so check the right order still parses.
  assert.equal(parseDuration("1h30m"), 5400);
});

test("repeated-unit-is-null: a unit appearing twice gives null", () => {
  assert.equal(parseDuration("1h1h"), null);
  // The stub returns null for everything, so check the unit once still parses.
  assert.equal(parseDuration("1h"), 3600);
});

test("bare-number-is-seconds: a number with no unit is seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("decimal-part: a part can be a decimal number", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("spaces-between-parts: spaces between the parts are allowed", () => {
  assert.equal(parseDuration("1h 30m"), 5400);
});

test("upper-case-units: unit letters can be upper case", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test('combined-hours-minutes: "1h30m" is 5400 seconds', () => {
  assert.equal(parseDuration('1h30m'), 5400);
});

test('seconds-unit: "45s" is 45 seconds', () => {
  assert.equal(parseDuration('45s'), 45);
});

test('minutes-unit: "2m" is 120 seconds', () => {
  assert.equal(parseDuration('2m'), 120);
});

test('hours-unit: "1h" is 3600 seconds', () => {
  assert.equal(parseDuration('1h'), 3600);
});

test('three-units-combined: "1h30m15s" is 5415 seconds', () => {
  assert.equal(parseDuration('1h30m15s'), 5415);
});

